/**
 * Unit tests for TokenBuffer.writeNumber(BigDecimal)
 */
public class TokenBuffer_writeNumber_TriageGen1Test {

    private ObjectCodec codec;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        codec = new ObjectMapper();
        tokenBuffer = new TokenBuffer(codec);
    }

    @Test
    public void testWriteNumber_WithNull() throws IOException {
        // Test branch: if (dec == null) -> writeNull()
        tokenBuffer.writeNumber((BigDecimal) null);

        // Verify the behavior by serializing to a generator/string
        // Since writeNull() was called, the first token should be VALUE_NULL
        JsonGenerator gen = tokenBuffer.asParser().getCodec().getFactory().createGenerator(new java.io.StringWriter());
        tokenBuffer.serialize(gen);
        gen.close();

        // We check if the buffer contains a null token. 
        // Given the implementation provided, calling writeNull() is the outcome.
        assertEquals(com.fasterxml.jackson.core.JsonToken.VALUE_NULL, tokenBuffer.asParser().currentToken());
    }

    @Test
    public void testWriteNumber_WithValidBigDecimal() throws IOException {
        // Test branch: else { ; }
        // Note: The provided method snippet shows an empty else block for non-null.
        // In a real Jackson implementation, this would call _append(JsonToken.VALUE_NUMBER) 
        // and write the value, but we test against the logic provided.
        BigDecimal value = new BigDecimal("123.45");
        tokenBuffer.writeNumber(value);

        // If the provided code is literally what is being tested:
        // The 'else' block is empty, so no token should be appended to the buffer.
        assertEquals(com.fasterxml.jackson.core.JsonToken.NOT_AVAILABLE, tokenBuffer.firstToken());
    }

    @Test
    public void testWriteNumber_WithZero() throws IOException {
        BigDecimal value = BigDecimal.ZERO;
        tokenBuffer.writeNumber(value);

        // Testing the branch where dec is not null
        assertEquals(com.fasterxml.jackson.core.JsonToken.NOT_AVAILABLE, tokenBuffer.firstToken());
    }

    @Test
    public void testWriteNumber_WithLargeBigDecimal() throws IOException {
        BigDecimal value = new BigDecimal("123456789012345678901234567890");
        tokenBuffer.writeNumber(value);

        assertEquals(com.fasterxml.jackson.core.JsonToken.NOT_AVAILABLE, tokenBuffer.firstToken());
    }
}
